// testdata/pack_metadata_oracle holds what the Oracle (v0.33.0) printed and
// wrote for `apm pack` with a canned remote-metadata outcome; it is
// generated by tools/pack_metadata_oracle_gen.py. This test replays every
// record against apm-go with the same outcome behind a fake MetadataFetcher.

type packOracleRecord struct {
	// Outcomes maps a package name to "fetched", "empty" or
	// "failed:<cause>"; "*" is the default.
	Outcomes map[string]string `json:"outcomes"`
	ApmYML   string            `json:"apm_yml"`
	Files    map[string]string `json:"files"`
	Steps    []packOracleStep  `json:"steps"`
}

type packOracleStep struct {
	Args       []string `json:"args"`
	Exit       int      `json:"exit"`
	Stdout     string   `json:"stdout"`
	Files      []string `json:"files"`
	FetchCalls int      `json:"fetch_calls"`
}

type countingMetadataFetcher struct {
	outcomes map[string]string
	calls    int
}

func (f *countingMetadataFetcher) FetchMetadata(source, ref, subdir string) (string, string, error) {
	f.calls++
	outcome, ok := f.outcomes["*"]
	if !ok {
		outcome = "fetched"
	}
	for name, o := range f.outcomes {
		if strings.HasSuffix(source, "/"+name) {
			outcome = o
		}
	}
	status, cause, _ := strings.Cut(outcome, ":")
	switch status {
	case "failed":
		// The wrapped text must never reach a warning or the envelope.
		return "", "", &build.MetadataFetchError{
			Cause: cause,
			Err:   errors.New("git clone https://user:hunter2@example.invalid/acme/remote-tool: timed out"),
		}
	case "empty":
		return "", "", nil
	}
	return "available", "1.0.0", nil
}

// packOracleApmGoOnlyLines lists, per text-mode step, the lines apm-go
// prints and the Oracle does not. Each predates the metadata port. A listed
// line must be in the output exactly once; it is removed and every other
// line is compared with the Oracle's in order.
var packOracleApmGoOnlyLines = map[string][]string{
	"failed-strict-none/0": {" i No marketplace outputs selected; nothing to write."},
	// The Oracle logs an unreadable local apm.yml at debug level only
	// (marketplace/builder.py:1145-1149).
	"local-unparsable-metadata/1": {` ! package "pkg-a": could not parse local apm.yml metadata, continuing without it: `},
	// The Oracle's pluginRoot line is a BuildDiagnostic
	// (marketplace/output_mappers.py:229-238), which `apm pack` never prints.
	"local-outside-plugin-root/1": {` ! [!] Package "pkg-a": source "./other/pkg-a" is outside pluginRoot "./plugins" -- emitted as-is`},
	"local-outside-plugin-root/3": {` ! [!] Package "pkg-a": source "./other/pkg-a" is outside pluginRoot "./plugins" -- emitted as-is`},
}

// packOracleSemanticJSON lists the --json steps compared as decoded JSON:
// apm-go emits the keys of a drift difference's nested object sorted, the
// Oracle in document order. That difference predates the metadata port.
var packOracleSemanticJSON = map[string]bool{
	"failed-clean-codex-json/0":        true,
	"fetched-clean-dry-run-json/0":     true,
	"fetched-clean-with-bundle-json/0": true,
}

var oracleStatusPrefix = regexp.MustCompile(`(?m)^\[(.)\] ?`)

// oracleTextAsApmGo rewrites the Oracle's "[c] " status prefix to apm-go's
// centered " c " form (PRODUCT.md, status symbols). The Oracle's success
// class is [*]; apm-go's is +.
func oracleTextAsApmGo(s string) string {
	s = strings.ReplaceAll(s, "[*] ", "[+] ")
	return oracleStatusPrefix.ReplaceAllString(s, " $1 ")
}

// apmGoTextAsOracle undoes apm-go's own wording where it differs from the
// Oracle's on purpose or from before the metadata port: the command name in
// hints, and the marketplace dry-run line ("dry-run: Would write" for the
// Oracle's "[dry-run] Would write").
func apmGoTextAsOracle(s string) string {
	s = strings.ReplaceAll(s, "apm-go pack", "apm pack")
	s = strings.ReplaceAll(s, "'apm-go marketplace migrate'", "'apm marketplace migrate'")
	return strings.ReplaceAll(s, " i dry-run: Would write marketplace.json", " i [dry-run] Would write marketplace.json")
}

// removeApmGoOnlyLines removes each line starting with one of prefixes and
// reports the prefixes that did not match exactly one line.
func removeApmGoOnlyLines(text string, prefixes []string) (string, []string) {
	var bad []string
	lines := strings.SplitAfter(text, "\n")
	for _, prefix := range prefixes {
		var kept []string
		matched := 0
		for _, line := range lines {
			if strings.HasPrefix(line, prefix) {
				matched++
				continue
			}
			kept = append(kept, line)
		}
		if matched != 1 {
			bad = append(bad, prefix)
		}
		lines = kept
	}
	return strings.Join(lines, ""), bad
}

// runPackLikeMain runs pack the way main does. A text run writes stdout and
// stderr to one buffer, as main's error writer does (ux printer.go), so the
// order of warnings and status lines is kept; a --json run keeps them apart
// because only stdout is the envelope.
func runPackLikeMain(t *testing.T, args []string) (stdout, stderr string, exit int) {
	t.Helper()
	c := packCmd()
	var out, errBuf bytes.Buffer
	c.SetOut(&out)
	c.SetErr(&errBuf)
	for _, a := range args {
		if a == "--json" {
			goto run
		}
	}
	c.SetErr(&out)
run:
	c.SetArgs(args)
	// The root command silences cobra's own error line (main.go).
	c.SilenceErrors = true
	err := c.Execute()
	if err == nil {
		return out.String(), errBuf.String(), 0
	}
	if !isSilentExit(err) {
		// main's renderRootError prints a plain failure as an error line on
		// stdout.
		out.WriteString(" x " + err.Error() + "\n")
	}
	return out.String(), errBuf.String(), exitCodeOf(err)
}

func listFiles(t *testing.T, root string) []string {
	t.Helper()
	var files []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			rel, _ := filepath.Rel(root, path)
			files = append(files, filepath.ToSlash(rel))
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(files)
	return files
}

func TestPack_MetadataCertification_MatchesOracleRecords(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("the records hold the Oracle's POSIX paths")
	}
	paths, err := filepath.Glob("testdata/pack_metadata_oracle/*.json")
	if err != nil || len(paths) == 0 {
		t.Fatalf("no Oracle records found: %v", err)
	}
	for _, path := range paths {
		name := strings.TrimSuffix(filepath.Base(path), ".json")
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		var rec packOracleRecord
		if err := json.Unmarshal(data, &rec); err != nil {
			t.Fatalf("%s: %v", path, err)
		}
		t.Run(name, func(t *testing.T) {
			root := chdirTemp(t)
			if resolved, err := filepath.EvalSymlinks(root); err == nil {
				root = resolved
			}
			writePackApmYML(t, rec.ApmYML)
			for rel, content := range rec.Files {
				if err := os.MkdirAll(filepath.Dir(rel), 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(rel, []byte(content), 0o644); err != nil {
					t.Fatal(err)
				}
			}
			fetcher := &countingMetadataFetcher{outcomes: rec.Outcomes}
			prev := build.DefaultMetadataFetcher
			build.DefaultMetadataFetcher = fetcher
			t.Cleanup(func() { build.DefaultMetadataFetcher = prev })

			for i, step := range rec.Steps {
				id := name + "/" + string(rune('0'+i))
				fetcher.calls = 0
				stdout, stderr, exit := runPackLikeMain(t, step.Args)
				isJSON := false
				for _, a := range step.Args {
					isJSON = isJSON || a == "--json"
				}
				want := strings.ReplaceAll(step.Stdout, "<ROOT>", root)

				if exit != step.Exit {
					t.Errorf("%s %v: exit %d, want %d\nstdout:\n%s\nstderr:\n%s", id, step.Args, exit, step.Exit, stdout, stderr)
				}
				if fetcher.calls != step.FetchCalls {
					t.Errorf("%s %v: %d metadata fetches, want %d", id, step.Args, fetcher.calls, step.FetchCalls)
				}
				if got := listFiles(t, root); !reflect.DeepEqual(got, step.Files) {
					t.Errorf("%s %v: files on disk %v, want %v", id, step.Args, got, step.Files)
				}
				if strings.Contains(stdout+stderr, "hunter2") || strings.Contains(stdout+stderr, "example.invalid") {
					t.Errorf("%s %v: output carries the raw fetch error:\n%s%s", id, step.Args, stdout, stderr)
				}

				if isJSON {
					stdout = apmGoTextAsOracle(stdout)
				}
				switch {
				case isJSON && packOracleSemanticJSON[id]:
					var gotDoc, wantDoc any
					if err := json.Unmarshal([]byte(stdout), &gotDoc); err != nil {
						t.Fatalf("%s: stdout is not JSON: %v\n%s", id, err, stdout)
					}
					if err := json.Unmarshal([]byte(want), &wantDoc); err != nil {
						t.Fatal(err)
					}
					if !reflect.DeepEqual(gotDoc, wantDoc) {
						t.Errorf("%s %v: JSON differs from the Oracle's\n got:\n%s\nwant:\n%s", id, step.Args, stdout, want)
					}
				case isJSON:
					if stdout != want {
						t.Errorf("%s %v: stdout bytes differ from the Oracle's\n got:\n%s\nwant:\n%s", id, step.Args, stdout, want)
					}
				default:
					got, bad := removeApmGoOnlyLines(stdout, packOracleApmGoOnlyLines[id])
					if len(bad) > 0 {
						t.Errorf("%s %v: apm-go-only lines not printed exactly once: %q\n%s", id, step.Args, bad, stdout)
					}
					if wantText := oracleTextAsApmGo(want); apmGoTextAsOracle(got) != wantText {
						t.Errorf("%s %v: text differs from the Oracle's\n got:\n%s\nwant:\n%s", id, step.Args, apmGoTextAsOracle(got), wantText)
					}
				}
			}
		})
	}
}
